#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long mod;
    cin >> n >> mod;

    vector<long long> memory = {0, 1};
    long long total_sum = 1;

    auto add = [&](long long a, long long b) {
        return (a + b) % mod;
    };

    auto mult = [&](long long a, long long b) {
        return (a * b) % mod;
    };

    for (int i = 2; i <= n; ++i) {
        int sqrt_limit = (int)std::sqrt(i) + 1;
        long long current_value = total_sum;
        for (int f = 2; f < sqrt_limit; ++f) {
            current_value = add(current_value, memory[i / f]);
        }
        int boundary = i;
        for (int j = 1; j <= i / sqrt_limit; ++j) {
            int next_boundary = i / (j + 1);
            current_value = add(current_value, mult(boundary - next_boundary, memory[j]));
            boundary = next_boundary;
        }
        total_sum = add(total_sum, current_value);
        memory.push_back(current_value);
    }
    cout << memory.back() << "\n";

    return 0;
}
